fn one_diff(a: Str, b: Str) -> Bool {
  if a.len() != b.len() {
    return false
  }
  let ca = a.chars()
  let cb = b.chars()
  let diffs = range(0, ca.len()).filter(fn(i) => ca.get_or(i, "") != cb.get_or(i, ""))
  return diffs.len() == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  let pool = words.unique()
  var visited: Map[Str, Bool] = Map {}
  visited = visited.set(start, true)
  var frontier: List[Str] = [start]
  var depth = 1
  while frontier.len() > 0 {
    if frontier.contains(goal) {
      return depth
    }
    var level: List[Str] = []
    for w in frontier {
      for cand in pool {
        if not (visited.has(cand)) and one_diff(w, cand) {
          visited = visited.set(cand, true)
          level = level.push(cand)
        }
      }
    }
    frontier = level
    depth = depth + 1
  }
  return 0
}
